protocol Greeter {
    func hello() -> String
}

extension Greeter {
    func hello() -> String { "P-hello" }
    func bye() -> String { "P-bye" }
}

struct Ali: Greeter {
    func hello() -> String { "A-hello" }
    func bye() -> String { "A-bye" }
}

let g: any Greeter = Ali()
print(g.hello(), g.bye())
